terraform_source_code:
resource "aws_vpc" "core" {
  cidr_block = "10.20.0.0/16"
}

resource "aws_subnet" "app" {
  vpc_id     = aws_vpc.core.id
  cidr_block = "10.20.1.0/24"
}

resource "aws_subnet" "db" {
  vpc_id     = aws_vpc.core.id
  cidr_block = "10.20.2.0/24"
}

resource "aws_route_table" "internal" {
  vpc_id = aws_vpc.core.id
}

resource "aws_route_table_association" "app" {
  subnet_id      = aws_subnet.app.id
  route_table_id = aws_route_table.internal.id
}

resource "aws_route_table_association" "db" {
  subnet_id      = aws_subnet.db.id
  route_table_id = aws_route_table.internal.id
}

resource "aws_security_group" "app" {
  name   = "app-endpoints"
  vpc_id = aws_vpc.core.id
}

resource "aws_security_group" "db" {
  name   = "db-endpoints"
  vpc_id = aws_vpc.core.id
}

resource "aws_vpc_security_group_egress_rule" "app_to_db" {
  security_group_id            = aws_security_group.app.id
  referenced_security_group_id  = aws_security_group.db.id
  ip_protocol                  = "tcp"
  from_port                    = 5432
  to_port                      = 5432
}

resource "aws_vpc_security_group_ingress_rule" "db_from_app" {
  security_group_id            = aws_security_group.db.id
  referenced_security_group_id  = aws_security_group.app.id
  ip_protocol                  = "tcp"
  from_port                    = 5432
  to_port                      = 5432
}

resource "aws_network_interface" "app" {
  subnet_id       = aws_subnet.app.id
  private_ips     = ["10.20.1.10"]
  security_groups = [aws_security_group.app.id]
}

resource "aws_network_interface" "db" {
  subnet_id       = aws_subnet.db.id
  private_ips     = ["10.20.2.10"]
  security_groups = [aws_security_group.db.id]
}

resource "aws_network_acl" "app" {
  vpc_id = aws_vpc.core.id
}

resource "aws_network_acl_association" "app" {
  subnet_id      = aws_subnet.app.id
  network_acl_id = aws_network_acl.app.id
}

resource "aws_network_acl_rule" "app_outbound_to_db" {
  network_acl_id = aws_network_acl.app.id
  egress         = true
  rule_number    = 100
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "10.20.2.0/24"
  from_port      = 5432
  to_port        = 5432
}

resource "aws_network_acl_rule" "app_inbound_return" {
  network_acl_id = aws_network_acl.app.id
  egress         = false
  rule_number    = 100
  protocol       = "6"
  rule_action    = "allow"
  cidr_block     = "10.20.2.0/24"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl" "db" {
  vpc_id = aws_vpc.core.id
}

resource "aws_network_acl_association" "db" {
  subnet_id      = aws_subnet.db.id
